CREATE OR REPLACE FUNCTION public.prevent_canonical_column_mutation()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
    frozen_columns text[] := string_to_array(TG_ARGV[0], ',');
    old_row jsonb := to_jsonb(OLD);
    new_row jsonb := to_jsonb(NEW);
    guarded text;
BEGIN
    FOREACH guarded IN ARRAY frozen_columns LOOP
        IF old_row -> guarded IS DISTINCT FROM new_row -> guarded THEN
            RAISE EXCEPTION '%.% is immutable', TG_TABLE_NAME, guarded;
        END IF;
    END LOOP;
    RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.prevent_evidence_lock_reset()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
    IF TG_OP = 'INSERT' THEN
        IF NEW.scientific_evidence_locked_at IS NOT NULL THEN
            RAISE EXCEPTION
                'experiments.scientific_evidence_locked_at cannot be set before scientific evidence is complete';
        END IF;
        RETURN NEW;
    END IF;
    IF OLD.scientific_evidence_locked_at IS NULL AND NEW.scientific_evidence_locked_at IS NOT NULL THEN
        IF NOT pipeline_run_scientific_evidence_complete(OLD.id) THEN
            RAISE EXCEPTION
                'experiments.scientific_evidence_locked_at cannot be set before scientific evidence is complete';
        END IF;
        NEW.scientific_evidence_locked_at := statement_timestamp();
    ELSIF OLD.scientific_evidence_locked_at IS NOT NULL
        AND NEW.scientific_evidence_locked_at IS DISTINCT FROM OLD.scientific_evidence_locked_at THEN
        RAISE EXCEPTION
            'experiments.scientific_evidence_locked_at cannot be changed once the run is locked';
    END IF;
    RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.prevent_experiment_lineage_violation()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
    parent_row record;
BEGIN
    IF TG_OP = 'UPDATE' THEN
        IF NEW.parent_pipeline_run_id IS DISTINCT FROM OLD.parent_pipeline_run_id
            OR NEW.change_set IS DISTINCT FROM OLD.change_set
            OR NEW.intent IS DISTINCT FROM OLD.intent THEN
            RAISE EXCEPTION
                'experiments.parent_pipeline_run_id, change_set and intent are insert-only';
        END IF;
        IF OLD.source_dataset_id IS NOT NULL
            AND NEW.source_dataset_id IS DISTINCT FROM OLD.source_dataset_id THEN
            RAISE EXCEPTION 'experiments.source_dataset_id is write-once';
        END IF;
        IF NEW.split_plan_id IS DISTINCT FROM OLD.split_plan_id THEN
            IF OLD.split_plan_id IS NOT NULL THEN
                RAISE EXCEPTION 'experiments.split_plan_id is write-once';
            END IF;
            IF OLD.scientific_evidence_locked_at IS NOT NULL THEN
                RAISE EXCEPTION
                    'experiments.split_plan_id cannot be set after the run is locked';
            END IF;
        END IF;
    END IF;
    IF NEW.change_set IS NOT NULL THEN
        SELECT workspace_id, project_id, source_dataset_id, split_plan_id
          INTO parent_row
          FROM experiments
         WHERE id = NEW.parent_pipeline_run_id;
        IF NOT FOUND OR parent_row.workspace_id IS DISTINCT FROM NEW.workspace_id THEN
            RAISE EXCEPTION 'branch parent must exist in the same workspace';
        END IF;
        IF NEW.project_id IS NULL
            OR NEW.project_id IS DISTINCT FROM parent_row.project_id THEN
            RAISE EXCEPTION 'branch must share project_id with its parent';
        END IF;
        IF NEW.source_dataset_id IS NULL
            OR NEW.source_dataset_id IS DISTINCT FROM parent_row.source_dataset_id THEN
            RAISE EXCEPTION 'branch must share source_dataset_id with its parent';
        END IF;
        IF parent_row.split_plan_id IS NULL
            OR NEW.split_plan_id IS DISTINCT FROM parent_row.split_plan_id THEN
            RAISE EXCEPTION 'branch must share split_plan_id with its parent';
        END IF;
    END IF;
    RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.prevent_locked_candidate_evidence_mutation()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
    owner uuid;
BEGIN
    IF TG_OP <> 'INSERT' THEN
        owner := (to_jsonb(OLD) ->> TG_ARGV[0])::uuid;
        IF candidate_evidence_locked(owner) THEN
            RAISE EXCEPTION '% is frozen: scientific evidence for this pipeline run is locked', TG_TABLE_NAME;
        END IF;
    END IF;
    IF TG_OP = 'DELETE' THEN
        RETURN OLD;
    END IF;
    owner := (to_jsonb(NEW) ->> TG_ARGV[0])::uuid;
    IF candidate_evidence_locked(owner) THEN
        RAISE EXCEPTION '% is frozen: scientific evidence for this pipeline run is locked', TG_TABLE_NAME;
    END IF;
    RETURN NEW;
END;
$function$

