 LANGUAGE plpgsql
AS $function$
BEGIN
    IF TG_OP <> 'INSERT'
        AND evaluation_target_evidence_locked(OLD.candidate_id, OLD.model_version_id)
    THEN
        RAISE EXCEPTION '% is frozen: scientific evidence for this pipeline run is locked', TG_TABLE_NAME;
    END IF;
    IF TG_OP = 'DELETE' THEN
        RETURN OLD;
    END IF;
    IF evaluation_target_evidence_locked(NEW.candidate_id, NEW.model_version_id) THEN
        RAISE EXCEPTION '% is frozen: scientific evidence for this pipeline run is locked', TG_TABLE_NAME;
    END IF;
    RETURN NEW;
